-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["731b84412226678a"] = { "Sotto l'occhio vigile dell'Order of Tirisfal, Dalaran divenne il principale centro di studi per i maghi di tutta la regione. I magocrati che governavano Dalaran fondarono il Kirin Tor, una setta specializzata incaricata di catalogare e studiare ogni incantesimo, artefatto e oggetto magico che l'umanità conoscesse all'epoca.", "." },
  ["731f724a938bb59e"] = { "Questo potrebbe richiedere altre indagini. Non so se ho abbastanza potere per combattere gli spiriti dei miei consanguinei morti... figuriamoci per scendere nelle profondità di Dor'danil e trovare il pomolo.\n\n(Nota: durante i miei preparativi ad Astranaar, ho conosciuto di recente un cacciatore nano che ha passato buona parte del suo tempo a ⟦Ashenvale=Valtetra⟧ cercando di aiutare il mio popolo. Veniva da un luogo chiamato ⟦Stormwind=Roccavento⟧.\n\nUna sera abbiamo parlato davanti a qualche boccale di birra, e i suoi racconti mi hanno dato nuova speranza di trovare il pomolo...", "." },
  ["733ee1b2d96ba0b7"] = { "la sua paura più grande:\n\nLys Ladimore\nAmata moglie e madre\n\nL'apprensione di Morgan si tramutò in sgomento e poi in dolore, e lui cadde in ginocchio piangendo. Per ore fissò quell'unica tomba, implorando il perdono della fredda pietra e singhiozzando scuse. Poi, ore dopo, qualcosa in lui si spezzò e cominciò a scagliarsi contro tutto. Sguainò la spada e prese a tempestare di colpi le lapidi, urlando di rabbia. Accecato dalla furia, menava fendenti all'impazzata, attirando l'attenzione", "." },
  ["73a0825bfab64249"] = { "Alcuni ipotizzarono che la sconcertante letargia fosse causata da una strana malattia che colpiva solo gli orchi. Ma l'arcimago Antonidas di Dalaran avanzò un'ipotesi diversa. Studiando quel poco che riuscì a trovare sulla storia degli orchi, Antonidas scoprì che da generazioni gli orchi erano sotto l'influsso paralizzante di un potere demoniaco.", "." },
  ["73b627d65954adaa"] = { "Giorno 1:\n\nDalle sei del mattino alle undici - accampamento superiore\n\nDalle undici alle undici e mezza - pausa, pranzo\n\nDalle undici e mezza alle quattro del pomeriggio - passo del canyon\n\nDalle quattro alle sette e mezza di sera - accampamento superiore\n\nGiorno 2:\n\nStesso orario del giorno 1\n\nGiorno 3:\n\nStesso orario\n\nGiorno 4:\n\nStesso orario, con un'eccezione. Poco prima del tramonto, Thorsen mi ha chiesto di coprirlo mentre scendeva di nascosto per il passo del canyon. Ho pensato che andasse a incontrare i nostri agenti.\n\nMa è tornato un'ora dopo. Questo mi ha sorpreso. Speravo che avesse incontrato i nostri agenti e che sarebbe tornato con Kurzen. Qualcosa non va.", "." },
  ["73cf438f8fbb90f8"] = { "Invocando il suo antico amore, Malfurion Stormrage, Tyrande riuscì a rafforzare le sue difese e a respingere la Legione. Con l'aiuto di Malfurion, la natura stessa insorse per sconfiggere la Legione e i suoi alleati del Flagello.", "." },
  ["73d107a933628e8d"] = { "Elune ha esaudito i miei desideri. Le vite dei miei compagni caduti non saranno state vane, e vendicherò la loro morte con la Scythe of Elune. È un oggetto antico, un ramo di legno ritorto e nodoso che potrebbe essere più vecchio persino dei kaldorei.\n\nPer molte ore ho esaminato lo strumento che la dea mi ha concesso. Non è un'arma comune, questo è certo, né un semplice strumento magico. Con essa... è come se le barriere del tempo e dello spazio si indebolissero.\n\nTenendo la Scythe", "." },
})
